import{_ as a,o as t,c as e,ag as o}from"./chunks/framework.KxDd3USm.js";const c=JSON.parse('{"title":"99.3 上午卷补充题","description":"","frontmatter":{},"headers":[],"relativePath":"99-考前全真模拟卷/03-上午卷补充题.md","filePath":"99-考前全真模拟卷/03-上午卷补充题.md"}'),n={name:"99-考前全真模拟卷/03-上午卷补充题.md"};function p(s,r,_,b,l,i){return t(),e("div",null,[...r[0]||(r[0]=[o('<h1 id="_99-3-上午卷补充题" tabindex="-1">99.3 上午卷补充题 <a class="header-anchor" href="#_99-3-上午卷补充题" aria-label="Permalink to &quot;99.3 上午卷补充题&quot;">​</a></h1><blockquote><p>这 6 道题覆盖前文 75 题没考到、但属于高频考点的三块内容：数据结构（关键路径与散列表平均查找长度）、软件工程（逻辑覆盖强弱排序）、数学与多媒体（采样定理／颜色空间／JPEG 压缩流程）。同样建议限时作答，答案在文末&quot;补充题解析&quot;。</p></blockquote><h3 id="第一组-数据结构-关键路径与散列表-asl-★★★" tabindex="-1">第一组　数据结构：关键路径与散列表 ASL ★★★ <a class="header-anchor" href="#第一组-数据结构-关键路径与散列表-asl-★★★" aria-label="Permalink to &quot;第一组　数据结构：关键路径与散列表 ASL ★★★&quot;">​</a></h3><p><strong>补充 1.</strong> 某 AOE 网（用边表示活动、顶点表示事件）中各活动持续时间为：1→2 为 4，1→3 为 3，2→4 为 5，3→4 为 6，3→5 为 2，4→5 为 3，2→5 为 4。则从起点事件 1 到终点事件 5 的关键路径长度（即工程的最短完工时间）为（ ）。</p><p>A. 10<br> B. 11<br> C. 12<br> D. 13</p><p><strong>补充 2.</strong> 散列表长度为 10，散列函数 H(key)=key mod 7，采用线性探测法处理冲突。依次插入关键字 8、15、1、22、13 后，查找关键字 22 所需的比较次数为（ ）。</p><p>A. 2<br> B. 3<br> C. 4<br> D. 5</p><h3 id="第二组-软件工程-逻辑覆盖强弱排序-★★★" tabindex="-1">第二组　软件工程：逻辑覆盖强弱排序 ★★★ <a class="header-anchor" href="#第二组-软件工程-逻辑覆盖强弱排序-★★★" aria-label="Permalink to &quot;第二组　软件工程：逻辑覆盖强弱排序 ★★★&quot;">​</a></h3><p><strong>补充 3.</strong> 按覆盖标准的严格程度，从较弱到较强（条件覆盖认为不比判定覆盖强）排列逻辑覆盖，正确的顺序是（ ）。</p><p>A. 语句覆盖 → 判定覆盖 → 条件覆盖 → 判定/条件覆盖 → 条件组合覆盖 → 路径覆盖<br> B. 路径覆盖 → 条件组合覆盖 → 判定/条件覆盖 → 条件覆盖 → 判定覆盖 → 语句覆盖<br> C. 语句覆盖 → 条件覆盖 → 判定覆盖 → 条件组合覆盖 → 判定/条件覆盖 → 路径覆盖<br> D. 判定覆盖 → 语句覆盖 → 条件覆盖 → 条件组合覆盖 → 路径覆盖 → 判定/条件覆盖</p><h3 id="第三组-数学与多媒体-采样定理、颜色空间、jpeg-步骤-★★" tabindex="-1">第三组　数学与多媒体：采样定理、颜色空间、JPEG 步骤 ★★ <a class="header-anchor" href="#第三组-数学与多媒体-采样定理、颜色空间、jpeg-步骤-★★" aria-label="Permalink to &quot;第三组　数学与多媒体：采样定理、颜色空间、JPEG 步骤 ★★&quot;">​</a></h3><p><strong>补充 4.</strong> 以 8 kHz 的采样率对一段模拟信号采样。根据采样定理，为保证能从离散样本无失真地恢复原信号，原信号的最高频率不能超过（ ）。</p><p>A. 4 kHz<br> B. 8 kHz<br> C. 16 kHz<br> D. 2 kHz</p><p><strong>补充 5.</strong> 视频传输与压缩中，把亮度与色度分离开（人眼对亮度更敏感），便于对色度成分进行更大程度压缩的颜色空间是（ ）。</p><p>A. RGB<br> B. CMYK<br> C. YCbCr（YUV）<br> D. Lab</p><p><strong>补充 6.</strong> JPEG 静态图像压缩的核心流程，正确顺序是（ ）。</p><p>A. DCT 变换 → 量化 → Z 字形扫描 → 熵编码<br> B. 量化 → DCT 变换 → 熵编码 → Z 字形扫描<br> C. 熵编码 → 量化 → DCT 变换 → Z 字形扫描<br> D. DCT 变换 → 熵编码 → 量化 → Z 字形扫描</p><hr>',18)])])}const h=a(n,[["render",p]]);export{c as __pageData,h as default};
